def test_concurrent_put_and_delete_in_one_directory(server, tmp_path):
    # Deleting the only blob of "d/" removes the directory; a put into "d/"
    # running at the same time must still succeed, not trip over the removal.
    host, port = server.server_address[:2]
    errors: list[str] = []

    def worker(key: str, also_delete: bool) -> None:
        connection = http.client.HTTPConnection(host, port, timeout=10)
        try:
            for i in range(150):
                status, body = put(connection, key, str(i).encode())
                if status != 201:
                    errors.append(f"PUT {key}: {status} {body}")
                if also_delete:
                    resp, _ = delete(connection, key)
                    if resp.status != 204:
                        errors.append(f"DELETE {key}: {resp.status}")
        except Exception as exc:  # e.g. the server dropped the connection
            errors.append(f"{key}: {exc!r}")
        finally:
            connection.close()

    threads = [
        threading.Thread(target=worker, args=("d/kept", False)),
        threading.Thread(target=worker, args=("d/churn", True)),
        threading.Thread(target=worker, args=("d/e/churn", True)),
    ]
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()

    assert errors == []
    connection = http.client.HTTPConnection(host, port, timeout=5)
    try:
        assert [b["key"] for b in list_blobs(connection)] == ["d/kept"]
    finally:
        connection.close()
    assert_nothing_escaped(tmp_path)

